/* Print the complete blank creative brief, even when its screen disclosure is closed. */
@media print {
  .page-creative .creative-template::details-content { content-visibility: visible !important; display: block !important; }
  .page-creative .creative-template > :not(summary) { display: block !important; }
  .page-creative .creative-template summary { cursor: default; list-style: none; break-after: avoid; }
  .page-creative .creative-template summary::marker { content: ""; }
  .page-creative .creative-template summary::-webkit-details-marker { display: none; }
  .page-creative .creative-template pre { overflow: visible; break-inside: auto; background: white; color: black; }
  .page-creative .creative-print-help { display: none; }
}
